game_api:
function getState() {
  const cart = update();
  const finished = cart.titleState === 2 && cart.raceState >= 3;
  return {
    schemaVersion: "1.0.0",
    gameId: GAME_ID,
    timestampMs: Date.now(),
    gameTimeMs: readyFrame === null ? 0 : Math.max(0, cart.frame - readyFrame) * 1000 / 60,
    status: error ? "error" : resetting ? "resetting" : outcome ||
      (ready ? "playing" : cart.raceState === 1 ? "countdown" : "loading"),
    is_actionable: !!ready,
    terminal: { isTerminal: outcome !== null, outcome },
    game_state: {
      task_id: taskId, track: TRACKS[cart.level] || "", level: cart.level,
      title_state: cart.titleState, race_state: cart.raceState,
      lap: cart.lap, laps_total: 3, race_finished: finished,
      finish_position: finished ? cart.finishPosition : 0,
      tokens_total: cart.totalTokens, opponents: cart.opponents,
      position: cart.position, track_length: cart.trackLength,
      speed: cart.speed, player_x: cart.playerX, drift: cart.drift,
      race_epoch: cart.epoch, is_custom: cart.isCustom, error
    },
    metrics: {
      lap_progress: lapBest, race_progress: raceBest, podium_progress: podiumBest,
      tokens_collected: cart.tokens,
      laps_completed: Math.min(3, Math.max(0, cart.lap - 1))
    },
    provenance: {
      game_state: "engine_hook", metrics: "engine_hook", gameTimeMs: "engine_hook",
      "game_state.task_id": "dom"
    }
  };
}
